import http.server, socket, threading, time, sys, io
class H(http.server.BaseHTTPRequestHandler):
    protocol_version="HTTP/1.1"
    def log_message(self,*a): pass
    def _send(self,code,body=b"",close=False):
        self.send_response(code)
        self.send_header("Content-Length",str(len(body)))
        if close: self.send_header("Connection","close"); self.close_connection=True
        self.end_headers()
        if self.command!="HEAD": self.wfile.write(body)
    def do_GET(self):
        self._send(204 if self.path=="/d" else 200, b"" if self.path=="/d" else b"ok")
    def do_POST(self):
        n=int(self.headers.get("Content-Length") or 0)
        if n>8192: return self._send(413,b'{"e":1}',close=True)
        self.rfile.read(n); self._send(200,b"ok")
